"""Write a native SPECTRA-PKA input file from a ``CampaignSpec``.

Only labels seen in the upstream manual and example inputs are emitted, because an
unrecognised label makes the program stop. User data files are never modified: they are
linked (or, if linking fails, copied) into the run directory under short names, so the input
file never needs long site paths and the originals stay untouched.

The ``columns=`` block carries four columns (file, ratio, element, mass number). The upstream
examples that also supply the two ``ngamma_*_mass`` columns do so for ``do_ngamma_estimate``,
which this adapter does not enable. The header names go on the ``columns=`` line itself.
"""

from __future__ import annotations

import hashlib
import os
import shutil
from dataclasses import dataclass
from pathlib import Path

from matsim_agents.backends.external.spectra_pka.config import CampaignSpec
from matsim_agents.core.hashing import sha256_file

INPUT_NAME = "spectra_pka.in"
FLUX_LINK = "flux.dat"
PKA_FILETYPE = 2
COLUMNS = ("pka_filename", "pka_ratios", "parent_ele", "parent_num")


class InputError(ValueError):
    """The campaign cannot be expressed as a native input file."""


@dataclass(frozen=True)
class StagedInputs:
    run_dir: Path
    input_file: Path
    input_sha256: str
    data_sha256: dict[str, str]  # staged name -> sha256 of the user's file
    staged_names: dict[str, str]  # staged name -> original path
    results_stub: str


def _fortran_bool(value: bool) -> str:
    return ".true." if value else ".false."


def _check_name(name: str) -> str:
    if any(c in name for c in ('"', "\n", "\r", "\0")):
        raise InputError(f"unsafe characters in input value {name!r}")
    return name


def pka_link_name(element: str, number: int) -> str:
    return f"pka_{element}{number:03d}.asc"


def build_input_text(spec: CampaignSpec) -> str:
    """The native input text. Values come only from the validated spec."""
    if spec.options.do_mtd_sums and PKA_FILETYPE != 2:
        raise InputError("do_mtd_sums requires pka_filetype=2")
    lines = [
        "# generated by matsim-agents; SPECTRA-PKA is external software",
        f"# scenario: {spec.scenario_id}",
        f'flux_filename="{FLUX_LINK}"',
        f'results_stub="{_check_name(spec.results_stub)}"',
        f"num_columns={len(COLUMNS)}",
        # Headers must share the ``columns=`` line: read_input.f90 takes them from the label's
        # value and reads the following lines as data rows.
        "columns= " + " ".join(COLUMNS),
    ]
    total = 0.0
    for ch in spec.channels:
        name = pka_link_name(ch.parent_ele, ch.parent_num)
        ratio = ch.atom_fraction / spec.composition[ch.parent_ele]
        total += ratio
        lines.append(f'"{name}" {ratio:.10f} {ch.parent_ele} {ch.parent_num}')
    lines += [
        f"number_pka_files={len(spec.channels)}",
        f"flux_norm_type={spec.flux.norm_type}",
        f"pka_filetype={PKA_FILETYPE}",
        f"do_mtd_sums={_fortran_bool(spec.options.do_mtd_sums)}",
        f"do_global_sums={_fortran_bool(spec.options.do_global_sums)}",
        f"do_exclude_light_from_total={_fortran_bool(spec.options.do_exclude_light_from_total)}",
        f"energies_once_perfile={_fortran_bool(spec.options.energies_once_perfile)}",
        f"max_global_recoils={spec.options.max_global_recoils}",
    ]
    if spec.flux.rescale_value is not None:
        lines.append(f"flux_rescale_value={spec.flux.rescale_value!r}")
    return "\n".join(lines) + "\n"


def _link_or_copy(source: Path, target: Path) -> None:
    if target.is_symlink() or target.exists():
        target.unlink()
    try:
        os.symlink(source, target)
    except OSError:
        shutil.copyfile(source, target)


def stage_inputs(spec: CampaignSpec, run_dir: Path) -> StagedInputs:
    """Create ``run_dir``, link the user's data into it, and write the input file."""
    for ch in spec.channels:
        if not ch.pka_file.is_file():
            raise InputError(
                f"PKA file for {ch.parent_ele}{ch.parent_num} not found: {ch.pka_file}"
            )
    if not spec.flux.file.is_file():
        raise InputError(f"flux file not found: {spec.flux.file}")
    text = build_input_text(spec)
    run_dir.mkdir(parents=True, exist_ok=True)
    data_hashes: dict[str, str] = {}
    staged: dict[str, str] = {}
    for ch in spec.channels:
        name = pka_link_name(ch.parent_ele, ch.parent_num)
        _link_or_copy(ch.pka_file.resolve(), run_dir / name)
        data_hashes[name] = sha256_file(ch.pka_file)
        staged[name] = str(ch.pka_file)
    _link_or_copy(spec.flux.file.resolve(), run_dir / FLUX_LINK)
    data_hashes[FLUX_LINK] = sha256_file(spec.flux.file)
    staged[FLUX_LINK] = str(spec.flux.file)
    input_file = run_dir / INPUT_NAME
    input_file.write_text(text)
    return StagedInputs(
        run_dir=run_dir,
        input_file=input_file,
        input_sha256=hashlib.sha256(text.encode()).hexdigest(),
        data_sha256=data_hashes,
        staged_names=staged,
        results_stub=spec.results_stub,
    )


__all__ = [
    "COLUMNS",
    "FLUX_LINK",
    "INPUT_NAME",
    "PKA_FILETYPE",
    "InputError",
    "StagedInputs",
    "build_input_text",
    "pka_link_name",
    "stage_inputs",
]
